// ════════════════════════════════════════
//  ESPAGNOL (Espagne) — niveaux B1 & B2
// ════════════════════════════════════════
(() => {
const { G, I, C, F, T, O, W, L, D, lesson, unit, course } = LS;

course('es', { flag: '🇪🇸', name: 'Espagnol', nameFr: 'Español (España)', tts: 'es-ES' }, [

// ─────────────── B1 ───────────────
unit('es_b1_1', 'B1', 'La salud', 'La santé', '🩺', '#ef4444', [
  lesson('En el médico', 'Chez le médecin',
    G('« Doler » : dire où on a mal',
      `<b>doler</b> fonctionne comme <b>gustar</b> : c'est la partie du corps qui est le sujet.<br><b>Me duele</b> la cabeza (singulier) = j'ai mal à la tête.<br><b>Me duelen</b> los pies (pluriel) = j'ai mal aux pieds.<br>Autres : <b>Tengo fiebre</b> (de la fièvre), <b>Tengo tos</b> (je tousse), <b>Estoy constipado/a</b> (je suis enrhumé·e !), <b>Estoy mareado/a</b> (j'ai la nausée / le vertige).<br>Conseil : <b>Debe</b> + infinitif (vous devez).`,
      [['Me duele mucho la garganta.', 'J\'ai très mal à la gorge.'], ['Me duelen los pies.', 'J\'ai mal aux pieds.'], ['Debe descansar y beber mucha agua.', 'Vous devez vous reposer et boire beaucoup d\'eau.']],
      'FAUX AMI : « constipado » = enrhumé, pas constipé ! Constipé se dit « estreñido ».'),
    [
      I('Me duele…', 'J\'ai mal à…', 'Me duele el estómago.', 'J\'ai mal à l\'estomac.'),
      I('Estoy constipado/a', 'Je suis enrhumé(e)', 'Estoy constipada desde el lunes.', 'Je suis enrhumée depuis lundi.'),
      I('la fiebre / la tos', 'la fièvre / la toux', '¿Tiene fiebre?', 'Vous avez de la fièvre ?'),
      I('la receta', 'l\'ordonnance', 'Le voy a hacer una receta.', 'Je vais vous faire une ordonnance.'),
      D('En el centro de salud', [
        ['Médica', 'Buenos días. A ver, ¿qué le pasa?', 'Bonjour. Voyons, qu\'est-ce qui ne va pas ?'],
        ['Paciente', 'Me duele la garganta y tengo mucha tos. Estoy muy cansado.', 'J\'ai mal à la gorge et je tousse beaucoup. Je suis très fatigué.'],
        ['Médica', '¿Tiene fiebre?', 'Vous avez de la fièvre ?'],
        ['Paciente', 'Tuve treinta y ocho y medio anoche.', 'J\'avais 38,5 hier soir.'],
        ['Médica', 'Será un virus. Debe quedarse en casa dos días y beber mucho líquido.', 'Ça doit être un virus. Restez chez vous deux jours et buvez beaucoup.'],
      ], [
        ['Quels sont les symptômes ?', ['Mal de gorge, toux, fatigue', 'Mal de dos', 'Mal au ventre', 'Mal aux dents']],
        ['Que conseille la médecin ?', ['Rester à la maison et boire', 'Faire du sport', 'Aller à l\'hôpital', 'Prendre des antibiotiques']],
      ]),
      F('Me ___ las piernas.', ['duelen', 'duele', 'dolen', 'duelo'], 'J\'ai mal aux jambes.', '« las piernas » est pluriel → duelen.'),
      F('Me ___ la cabeza.', ['duele', 'duelen', 'tengo', 'estoy'], 'J\'ai mal à la tête.'),
      C('« Estoy constipado » signifie :', ['Je suis enrhumé', 'Je suis constipé', 'Je suis fatigué', 'Je suis stressé']),
      O('Vous devez vous reposer.', 'Debe descansar', ['tiene']),
      W('J\'ai de la fièvre.', 'Tengo fiebre|Yo tengo fiebre'),
      L('Me duele la rodilla cuando camino.', 'J\'ai mal au genou quand je marche.'),
      T('Que dois-je faire ?', ['¿Qué debo hacer?', '¿Qué tengo hacer?', '¿Qué debo de hago?', '¿Qué deber hacer yo?']),
    ]),

  lesson('En la farmacia', 'À la pharmacie',
    G('L\'obligation : tener que / hay que / no hace falta',
      `<b>tener que</b> + infinitif = devoir (obligation personnelle) : <b>Tiene que</b> tomarlo con comida.<br><b>hay que</b> + infinitif = il faut (général) : <b>Hay que</b> descansar.<br><b>deber</b> + infinitif = devoir (conseil) : <b>Debe</b> beber agua.<br><b>no hace falta</b> = pas besoin : <b>No hace falta</b> receta.<br>Passé : <b>tuve que</b> esperar (j'ai dû attendre).`,
      [['Tengo que ir a la farmacia.', 'Je dois aller à la pharmacie.'], ['No hace falta pedir cita.', 'Pas besoin de prendre rendez-vous.'], ['Tuve que esperar dos horas.', 'J\'ai dû attendre deux heures.']],
      'N\'oubliez pas le « que » : « Tengo que ir », jamais « Tengo ir » ni « Tengo de ir ».'),
    [
      I('tener que', 'devoir (obligation)', 'Tengo que trabajar mañana.', 'Je dois travailler demain.'),
      I('no hace falta', 'ce n\'est pas nécessaire', 'No hace falta pagar.', 'Pas besoin de payer.'),
      I('la pastilla', 'le comprimé', 'Tome una pastilla cada ocho horas.', 'Prenez un comprimé toutes les huit heures.'),
      I('en ayunas', 'à jeun', 'Hay que tomarlo en ayunas.', 'Il faut le prendre à jeun.'),
      D('En la farmacia', [
        ['Farmacéutica', 'Buenas tardes, ¿qué necesita?', 'Bonjour, de quoi avez-vous besoin ?'],
        ['Cliente', 'Tengo esta receta. ¿Tengo que tomar las pastillas con comida?', 'J\'ai cette ordonnance. Je dois prendre les comprimés en mangeant ?'],
        ['Farmacéutica', 'Sí, tiene que tomarlas después de las comidas. Y no puede beber alcohol.', 'Oui, à prendre après les repas. Et pas d\'alcool.'],
        ['Cliente', '¿Tengo que terminar la caja?', 'Je dois finir la boîte ?'],
        ['Farmacéutica', 'Sí, aunque se encuentre mejor.', 'Oui, même si vous vous sentez mieux.'],
      ], [
        ['Quand prendre les comprimés ?', ['Après les repas', 'Avant les repas', 'À jeun', 'Le soir seulement']],
        ['Qu\'est-ce qui est interdit ?', ['L\'alcool', 'Le café', 'Le sport', 'Le lait']],
      ]),
      F('Tengo ___ ir al médico.', ['que', 'de', 'a', '—'], 'Je dois aller chez le médecin.'),
      F('No hace ___ pedir cita.', ['falta', 'falto', 'necesario de', 'que'], 'Pas besoin de prendre rendez-vous.'),
      C('« J\'ai dû attendre » :', ['Tuve que esperar.', 'Tengo que esperé.', 'Tenía esperado.', 'Debí de esperado.']),
      O('Vous ne pouvez pas boire d\'alcool.', 'No puede beber alcohol', ['debe']),
      W('Je dois aller à la pharmacie.', 'Tengo que ir a la farmacia|Yo tengo que ir a la farmacia'),
      L('Tome una pastilla cada ocho horas.', 'Prenez un comprimé toutes les huit heures.'),
      T('Il faut se reposer.', ['Hay que descansar.', 'Hay descansar.', 'Tiene descansar.', 'Es que descansar.']),
    ]),

  lesson('Comparar', 'Comparer',
    G('Comparatifs et superlatifs',
      `Supériorité : <b>más</b> … <b>que</b> : más barato que… · Infériorité : <b>menos</b> … <b>que</b>.<br>Irréguliers : <b>bueno → mejor</b> · <b>malo → peor</b> · <b>grande → mayor</b> (âge / importance) · <b>pequeño → menor</b>.<br>Égalité : <b>tan</b> + adjectif + <b>como</b> · <b>tanto/a</b> + nom + <b>como</b>.<br>Superlatif : <b>el / la más</b> … <b>de</b> : la playa más bonita <b>de</b> España. Absolu : -<b>ísimo</b> : buenísimo, carísimo.`,
      [['El tren es más rápido que el autobús.', 'Le train est plus rapide que le bus.'], ['Es el mejor restaurante de la ciudad.', 'C\'est le meilleur restaurant de la ville.'], ['Hoy no hace tanto calor como ayer.', 'Aujourd\'hui il ne fait pas aussi chaud qu\'hier.']],
      '« Mi hermano mayor » = mon grand frère (plus âgé). Pour la taille, on dit « más alto » ; pour une ville, « más grande ».'),
    [
      I('mejor / peor', 'meilleur / pire', 'Este café es mejor.', 'Ce café est meilleur.'),
      I('mayor / menor', 'plus âgé / plus jeune', 'Mi hermana menor vive en Lyon.', 'Ma petite sœur vit à Lyon.'),
      I('tan … como', 'aussi … que', 'Es tan alto como su padre.', 'Il est aussi grand que son père.'),
      I('-ísimo', 'très, extrêmement', '¡La paella está buenísima!', 'La paella est délicieuse !'),
      D('Elegir un gimnasio (choisir une salle de sport)', [
        ['Ana', '¿Cuál es mejor, el FitLife o el Body Club?', 'Laquelle est la meilleure, FitLife ou Body Club ?'],
        ['Rubén', 'El FitLife es más barato, pero el Body Club es más grande y más limpio.', 'FitLife est moins chère, mais Body Club est plus grande et plus propre.'],
        ['Ana', '¿El Body Club es mucho más caro?', 'Body Club est beaucoup plus chère ?'],
        ['Rubén', 'Diez euros más al mes. Pero tiene la mejor piscina de la ciudad.', 'Dix euros de plus par mois. Mais elle a la meilleure piscine de la ville.'],
      ], [
        ['Quelle salle est la moins chère ?', ['FitLife', 'Body Club', 'Même prix', 'On ne sait pas']],
        ['Avantage de Body Club ?', ['La meilleure piscine', 'Ouverte 24 h/24', 'Gratuite', 'Des cours de yoga']],
      ]),
      F('Madrid es más grande ___ Sevilla.', ['que', 'como', 'de', 'tan'], 'Madrid est plus grande que Séville.'),
      F('Es la playa más bonita ___ España.', ['de', 'en', 'que', 'del'], 'C\'est la plus belle plage d\'Espagne.'),
      C('Comparatif de « malo » :', ['peor', 'más malo que bien', 'pior', 'menor']),
      O('Le train est plus confortable que l\'avion.', 'El tren es más cómodo que el avión', ['como']),
      W('C\'est le meilleur hôtel de la ville.', 'Es el mejor hotel de la ciudad|Este es el mejor hotel de la ciudad'),
      L('Mi nuevo trabajo es mucho mejor que el anterior.', 'Mon nouveau travail est bien meilleur que l\'ancien.'),
      T('Ce n\'est pas aussi cher que je pensais.', ['No es tan caro como pensaba.', 'No es tan caro que pensaba.', 'No es tanto caro como pensaba.', 'No es más caro como pensaba.']),
    ]),
]),

unit('es_b1_2', 'B1', 'Experiencias', 'Expériences de vie', '🌍', '#3b82f6', [
  lesson('Cuando era pequeño…', 'Quand j\'étais petit…',
    G('L\'imparfait (pretérito imperfecto)',
      `Pour les <b>habitudes passées</b> et les <b>descriptions</b> (comme l'imparfait français).<br><b>-AR</b> : habl<b>aba</b>, habl<b>abas</b>, habl<b>aba</b>, habl<b>ábamos</b>, habl<b>abais</b>, habl<b>aban</b><br><b>-ER / -IR</b> : com<b>ía</b>, com<b>ías</b>, com<b>ía</b>, com<b>íamos</b>, com<b>íais</b>, com<b>ían</b><br>Seulement 3 irréguliers : ser → <b>era</b> · ir → <b>iba</b> · ver → <b>veía</b>.`,
      [['Cuando era pequeña, vivía en el campo.', 'Quand j\'étais petite, je vivais à la campagne.'], ['Todos los veranos íbamos a la playa.', 'Tous les étés nous allions à la plage.'], ['La casa tenía un jardín enorme.', 'La maison avait un immense jardin.']],
      'Bonne nouvelle : l\'imparfait espagnol est le temps le plus régulier de tous, et il s\'emploie presque exactement comme en français.'),
    [
      I('cuando era pequeño/a', 'quand j\'étais petit(e)', 'Cuando era pequeño, tenía un perro.', 'Quand j\'étais petit, j\'avais un chien.'),
      I('solía…', 'j\'avais l\'habitude de…', 'Solía pescar con mi abuelo.', 'J\'allais souvent pêcher avec mon grand-père.'),
      I('antes', 'avant, autrefois', 'Antes no había turistas aquí.', 'Autrefois il n\'y avait pas de touristes ici.'),
      I('la infancia', 'l\'enfance', 'Tuve una infancia feliz.', 'J\'ai eu une enfance heureuse.'),
      D('Recuerdos de infancia', [
        ['Nieta', 'Abuela, ¿cómo era la vida cuando eras joven?', 'Mamie, comment était la vie quand tu étais jeune ?'],
        ['Abuela', 'Muy diferente. Vivíamos en un pueblo y no había tele.', 'Très différente. On vivait dans un village et il n\'y avait pas de télé.'],
        ['Nieta', '¿Y qué hacíais por la noche?', 'Et que faisiez-vous le soir ?'],
        ['Abuela', 'Hablábamos, cantábamos… y mi padre contaba historias.', 'On discutait, on chantait… et mon père racontait des histoires.'],
      ], [
        ['Où vivait la grand-mère ?', ['Dans un village', 'À Madrid', 'Au bord de la mer', 'À l\'étranger']],
        ['Que faisait son père le soir ?', ['Il racontait des histoires', 'Il regardait la télé', 'Il travaillait', 'Il cuisinait']],
      ]),
      F('Cuando yo ___ niño, vivía en Málaga.', ['era', 'fui', 'estaba', 'soy'], 'Quand j\'étais enfant, je vivais à Malaga.'),
      F('Nosotros ___ siempre a la playa en verano.', ['íbamos', 'fuimos', 'vamos', 'ibamos de'], 'Nous allions toujours à la plage l\'été.'),
      C('« La maison avait trois chambres » :', ['La casa tenía tres dormitorios.', 'La casa tuvo tres dormitorios.', 'La casa ha tenido tres dormitorios.', 'La casa había tres dormitorios.']),
      O('Autrefois il n\'y avait pas de touristes.', 'Antes no había turistas', ['hubo']),
      W('Quand j\'étais petit(e), j\'avais un chat.', 'Cuando era pequeño, tenía un gato|Cuando era pequeña, tenía un gato|Cuando era pequeño tenía un gato|Cuando era pequeña tenía un gato|Cuando yo era pequeño, tenía un gato|Cuando yo era pequeña, tenía un gato'),
      L('Todos los domingos comíamos en casa de mis abuelos.', 'Tous les dimanches nous déjeunions chez mes grands-parents.'),
      T('Il faisait beau et les enfants jouaient.', ['Hacía sol y los niños jugaban.', 'Hizo sol y los niños jugaron.', 'Estaba sol y los niños jugaban.', 'Era sol y los niños jugaban.']),
    ]),

  lesson('Indefinido o imperfecto', 'Passé simple ou imparfait ?',
    G('Pretérito indefinido vs imperfecto',
      `<b>Imperfecto</b> = le décor, ce qui était en cours, l'habitude : Llovía. <b>Estaba durmiendo</b>.<br><b>Indefinido</b> = l'action ponctuelle, terminée, qui fait avancer l'histoire : El teléfono <b>sonó</b>.<br>→ <b>Estaba durmiendo cuando sonó el teléfono.</b><br>C'est la même logique qu'imparfait / passé composé en français.`,
      [['Cuando llegué, estaba lloviendo.', 'Quand je suis arrivé, il pleuvait.'], ['Mientras cenábamos, se fue la luz.', 'Pendant qu\'on dînait, il y a eu une coupure de courant.'], ['Era tarde cuando salimos.', 'Il était tard quand nous sommes sortis.']],
      'Action en cours dans le passé : « estaba + gérondif » (j\'étais en train de) — « Estaba cocinando cuando llamaste ».'),
    [
      I('mientras', 'pendant que', 'Mientras yo cocinaba, él puso la mesa.', 'Pendant que je cuisinais, il a mis la table.'),
      I('de repente', 'soudain', 'De repente, empezó a llover.', 'Soudain, il a commencé à pleuvoir.'),
      I('pasar', 'se passer, arriver', '¿Qué pasó?', 'Que s\'est-il passé ?'),
      I('al final', 'finalement', 'Al final, todo salió bien.', 'Finalement, tout s\'est bien passé.'),
      D('Una noche rara', [
        ['Max', 'Bueno, ¿y qué pasó?', 'Bon, et qu\'est-ce qui s\'est passé ?'],
        ['Lou', 'Era tarde y llovía. Yo volvía al hotel…', 'Il était tard et il pleuvait. Je rentrais à l\'hôtel…'],
        ['Max', '¿Y?', 'Et ?'],
        ['Lou', 'De repente, un hombre corrió hacia mí. Tenía algo en la mano.', 'Soudain, un homme a couru vers moi. Il avait quelque chose dans la main.'],
        ['Max', '¡Qué miedo! ¿Qué hiciste?', 'J\'aurais eu peur ! Qu\'as-tu fait ?'],
        ['Lou', '¡Nada! Solo me devolvió las llaves. ¡Se me habían caído en el restaurante!', 'Rien ! Il m\'a juste rendu mes clés. Elles étaient tombées au restaurant !'],
      ], [
        ['Quel temps faisait-il ?', ['Il pleuvait', 'Il neigeait', 'Il faisait beau', 'Il y avait du vent']],
        ['Que tenait l\'homme ?', ['Les clés de Lou', 'Un couteau', 'Un téléphone', 'Un parapluie']],
      ]),
      F('Yo ___ viendo la tele cuando llamaste.', ['estaba', 'estuve', 'estoy', 'era'], 'Je regardais la télé quand tu as appelé.'),
      F('Mientras cenábamos, ___ la alarma.', ['sonó', 'sonaba', 'suena', 'ha sonar'], 'Pendant qu\'on dînait, l\'alarme a sonné.'),
      C('« Que faisais-tu à minuit ? » :', ['¿Qué estabas haciendo a medianoche?', '¿Qué estuviste haciendo hacer a medianoche?', '¿Qué hacías hecho a medianoche?', '¿Qué haces a medianoche ayer?']),
      O('Il pleuvait quand nous sommes arrivés.', 'Llovía cuando llegamos', ['llegábamos']),
      W('Que s\'est-il passé ?', '¿Qué pasó?|Qué pasó|¿Qué ha pasado?|Qué ha pasado'),
      L('Cuando salí de casa, hacía mucho frío.', 'Quand je suis sorti de chez moi, il faisait très froid.'),
      T('Pendant que je dormais, il a neigé.', ['Mientras yo dormía, nevó.', 'Mientras dormí, nevaba.', 'Mientras yo dormí, nevó.', 'Durante yo dormía, nevó.']),
    ]),

  lesson('¿Desde cuándo?', 'Depuis combien de temps ?',
    G('Exprimer la durée : desde, hace… que, llevar + gérondif',
      `<b>desde</b> + date : Vivo aquí <b>desde</b> 2020.<br><b>hace</b> + durée + <b>que</b> + présent : <b>Hace</b> tres años <b>que</b> vivo aquí (ça fait trois ans que…).<br><b>llevar</b> + durée + <b>gérondif</b> (très espagnol) : <b>Llevo</b> tres años <b>viviendo</b> aquí.<br>Question : <b>¿Cuánto tiempo hace que</b>…? / <b>¿Cuánto tiempo llevas</b>…?<br><b>hace</b> + durée + passé = il y a : Llegué <b>hace</b> dos horas.`,
      [['¿Cuánto tiempo llevas en España?', 'Depuis combien de temps es-tu en Espagne ?'], ['La conozco desde el colegio.', 'Je la connais depuis l\'école.'], ['Todavía no he visitado Toledo.', 'Je n\'ai pas encore visité Tolède.']],
      'Comme en français, on utilise le présent pour « depuis » : « Vivo aquí desde 2020 ». Pas de passé composé comme en anglais.'),
    [
      I('desde', 'depuis (une date)', 'Está enfermo desde el viernes.', 'Il est malade depuis vendredi.'),
      I('llevar + gérondif', 'faire qqch depuis…', 'Llevo media hora esperando.', 'J\'attends depuis une demi-heure.'),
      I('ya / todavía no', 'déjà / pas encore', '¿Ya has comido? — Todavía no.', 'Tu as déjà mangé ? — Pas encore.'),
      I('mudarse', 'déménager', 'Nos mudamos aquí en 2020.', 'Nous avons emménagé ici en 2020.'),
      D('Una nueva vecina', [
        ['Vecino', '¿Cuánto tiempo hace que vive en Alicante?', 'Depuis combien de temps vivez-vous à Alicante ?'],
        ['Élise', 'Unos seis años. Nos mudamos desde Lyon en 2020.', 'Environ six ans. Nous sommes venus de Lyon en 2020.'],
        ['Vecino', '¡Y ya habla muy bien español!', 'Et vous parlez déjà très bien espagnol !'],
        ['Élise', '¡Gracias! Llevo seis años estudiando. Pero todavía no entiendo bien el andaluz.', 'Merci ! J\'étudie depuis six ans. Mais je ne comprends pas encore bien l\'accent andalou.'],
      ], [
        ['Depuis quand Élise vit-elle à Alicante ?', ['Environ 6 ans', '20 ans', '2 ans', 'Depuis toujours']],
        ['Qu\'est-ce qu\'elle ne comprend pas encore bien ?', ['L\'accent andalou', 'Le flamenco', 'Les horaires', 'Ses voisins']],
      ]),
      F('Vivo en Madrid ___ 2019.', ['desde', 'hace', 'durante', 'por'], 'J\'habite à Madrid depuis 2019.'),
      F('Llevo dos horas ___.', ['esperando', 'esperar', 'esperado', 'espero'], 'J\'attends depuis deux heures.'),
      C('« Ça fait cinq ans que je travaille ici » :', ['Hace cinco años que trabajo aquí.', 'Hace cinco años que he trabajado aquí desde.', 'Desde cinco años trabajo aquí.', 'Trabajo aquí hace cinco años que.']),
      O('Depuis combien de temps apprends-tu l\'espagnol ?', 'Cuánto tiempo llevas aprendiendo español', ['desde']),
      W('Je n\'ai pas encore mangé.', 'Todavía no he comido|Aún no he comido|Todavía no comí'),
      L('Llevo veinte minutos esperando el autobús.', 'J\'attends le bus depuis vingt minutes.'),
      T('Je la connais depuis l\'enfance.', ['La conozco desde la infancia.', 'La conozco hace la infancia.', 'Conozco la desde infancia.', 'La conocí desde la infancia.']),
    ]),
]),

unit('es_b1_3', 'B1', 'Casa y servicios', 'Logement et services', '🔑', '#84cc16', [
  lesson('Alquilar un piso', 'Louer un appartement',
    G('Les pronoms compléments : lo, la, le… et « se lo »',
      `COD : <b>lo</b> (le), <b>la</b> (la), <b>los</b>, <b>las</b>. COI : <b>le</b> (lui / vous), <b>les</b>. Aussi <b>me, te, nos, os</b>.<br>Place : <b>avant</b> le verbe conjugué : <b>Lo</b> veo mañana. No <b>la</b> conozco.<br><b>Collés</b> à l'infinitif, au gérondif et à l'impératif affirmatif : Voy a comprar<b>lo</b>. Díga<b>me</b>.<br>Deux pronoms : <b>le / les</b> devient <b>se</b> devant lo / la : Se <b>lo</b> doy (je le lui donne).`,
      [['¿El contrato? Se lo envío mañana.', 'Le contrat ? Je vous l\'envoie demain.'], ['No lo conozco.', 'Je ne le connais pas.'], ['¿Las llaves? Voy a dártelas.', 'Les clés ? Je vais te les donner.']],
      'Jamais « le lo » : on dit « se lo ». Et dans « Voy a comprarlo » / « Lo voy a comprar », les deux places sont correctes.'),
    [
      I('el alquiler', 'le loyer / la location', 'El alquiler es de 900 euros.', 'Le loyer est de 900 euros.'),
      I('el casero / la casera', 'le propriétaire (bailleur)', 'El casero vive en el bajo.', 'Le propriétaire habite au rez-de-chaussée.'),
      I('la fianza', 'la caution', 'Piden dos meses de fianza.', 'Ils demandent deux mois de caution.'),
      I('amueblado / gastos incluidos', 'meublé / charges comprises', 'Está amueblado y con gastos incluidos.', 'C\'est meublé, charges comprises.'),
      D('Visitar un piso', [
        ['Agente', 'Este es el salón. Tiene mucha luz, como ve.', 'Voici le salon. Très lumineux, comme vous voyez.'],
        ['Inquilina', 'Es precioso. ¿Cuánto es el alquiler?', 'Il est superbe. Quel est le loyer ?'],
        ['Agente', 'Novecientos euros al mes, sin gastos.', 'Neuf cents euros par mois, hors charges.'],
        ['Inquilina', '¿Y la fianza?', 'Et la caution ?'],
        ['Agente', 'Dos meses. Si quiere, hablo hoy con el casero y se lo confirmo mañana.', 'Deux mois. Si vous voulez, je parle au propriétaire aujourd\'hui et je vous le confirme demain.'],
      ], [
        ['Les charges sont-elles comprises ?', ['Non', 'Oui', 'En partie', 'On ne sait pas']],
        ['Combien de mois de caution ?', ['Deux', 'Un', 'Trois', 'Aucun']],
      ]),
      F('¿Conoces a Pedro? — Sí, ___ conozco.', ['lo', 'le lo', 'la', 'se'], 'Tu connais Pedro ? — Oui, je le connais.'),
      F('¿El libro? ___ lo doy mañana. (à lui)', ['Se', 'Le', 'Lo', 'Les'], 'Le livre ? Je le lui donne demain.', 'le + lo → se lo.'),
      C('« Je vais l\'acheter » (le livre) :', ['Voy a comprarlo.', 'Voy a lo comprar.', 'Voy a comprar le.', 'Lo voy a comprarlo.']),
      O('Je vous appelle demain.', 'Le llamo mañana', ['llámole']),
      W('Le loyer est de 800 euros.', 'El alquiler es de 800 euros|El alquiler es de ochocientos euros|El alquiler son 800 euros'),
      L('Ya la conozco, es mi vecina.', 'Je la connais déjà, c\'est ma voisine.'),
      T('Je ne le connais pas.', ['No lo conozco.', 'No conozco lo.', 'Lo no conozco.', 'No le lo conozco.']),
    ]),

  lesson('Reclamaciones', 'Problèmes et réclamations',
    G('« acabar de », « volver a » et se plaindre',
      `<b>acabar de</b> + infinitif = venir de : <b>Acabo de</b> comprar esta cafetera.<br><b>volver a</b> + infinitif = re-faire : La luz <b>ha vuelto a</b> fallar (la lumière a encore sauté).<br>Problèmes : <b>está estropeado/a</b> (en panne / abîmé) · <b>no funciona</b> · <b>está roto/a</b> (cassé).<br>Réclamer : <b>Quería poner una reclamación</b> · <b>Quería que me devolvieran el dinero</b> · <b>¿Puedo cambiarlo?</b>`,
      [['El ascensor está estropeado otra vez.', 'L\'ascenseur est encore en panne.'], ['Acabo de llegar.', 'Je viens d\'arriver.'], ['¿Me puede dar una hoja de reclamaciones?', 'Pouvez-vous me donner une feuille de réclamation ?']],
      'En Espagne, tout commerce doit avoir des « hojas de reclamaciones » officielles. Les demander suffit souvent à débloquer une situation !'),
    [
      I('estropeado/a', 'en panne', 'El coche está estropeado.', 'La voiture est en panne.'),
      I('acabar de', 'venir de', 'Acabamos de cenar.', 'Nous venons de dîner.'),
      I('devolver el dinero', 'rembourser', '¿Me pueden devolver el dinero?', 'Vous pouvez me rembourser ?'),
      I('cambiar', 'échanger', '¿Puedo cambiar esta chaqueta?', 'Je peux échanger cette veste ?'),
      D('En una tienda de electrodomésticos', [
        ['Dependiente', 'Buenos días, ¿en qué puedo ayudarle?', 'Bonjour, en quoi puis-je vous aider ?'],
        ['Cliente', 'Compré esta cafetera la semana pasada y ya está estropeada.', 'J\'ai acheté cette cafetière la semaine dernière et elle est déjà en panne.'],
        ['Dependiente', 'Lo siento. ¿Ha probado a apagarla y volver a encenderla?', 'Je suis désolé. Avez-vous essayé de l\'éteindre et la rallumer ?'],
        ['Cliente', 'Sí, varias veces. Quería que me devolvieran el dinero.', 'Oui, plusieurs fois. Je voudrais être remboursé.'],
        ['Dependiente', 'Por supuesto. ¿Tiene el tique?', 'Bien sûr. Vous avez le ticket ?'],
      ], [
        ['Quel appareil est en panne ?', ['Une cafetière', 'Un lave-linge', 'Un téléphone', 'Une télé']],
        ['Que demande le vendeur à la fin ?', ['Le ticket de caisse', 'Le numéro de téléphone', 'La carte bancaire', 'Le carton']],
      ]),
      F('Acabo ___ llegar a casa.', ['de', 'a', 'que', 'por'], 'Je viens de rentrer à la maison.'),
      F('La nevera está ___.', ['estropeada', 'estropeado', 'en pana', 'rompida'], 'Le frigo est en panne.', '« la nevera » est féminin.'),
      C('« Ça a encore planté » :', ['Ha vuelto a fallar.', 'Acaba de fallar otra vez de.', 'Refalló.', 'Ha fallado de nuevo-se.']),
      O('Je voudrais faire une réclamation.', 'Quería poner una reclamación', ['quiero me']),
      W('Je peux échanger ce pull ?', '¿Puedo cambiar este jersey?|Puedo cambiar este jersey|¿Puedo cambiar este suéter?|Puedo cambiar este suéter'),
      L('Lo siento, pero el ascensor está estropeado.', 'Je suis désolé, mais l\'ascenseur est en panne.'),
      T('Je viens d\'arriver.', ['Acabo de llegar.', 'Vengo de llegar.', 'Acabo llegar.', 'He acabado de llegado.'], '« Vengo de llegar » est un calque du français à éviter.'),
    ]),

  lesson('Al teléfono', 'Au téléphone',
    G('Téléphoner + le futur simple',
      `En Espagne, on décroche avec <b>¿Sí?</b>, <b>¿Diga?</b> ou <b>¿Dígame?</b><br><b>¿De parte de quién?</b> = C'est de la part de qui ? · <b>Ahora se pone</b> = Je vous le passe · <b>¿Quiere dejar un mensaje?</b><br><b>Futur simple</b> : infinitif + <b>é, ás, á, emos, éis, án</b> : llamar<b>é</b>, hablar<b>á</b>.<br>Irréguliers : tener → <b>tendré</b> · poder → <b>podré</b> · hacer → <b>haré</b> · decir → <b>diré</b> · salir → <b>saldré</b> · venir → <b>vendré</b> · saber → <b>sabré</b> · poner → <b>pondré</b> · querer → <b>querré</b>.`,
      [['¿Diga? — Hola, soy Ana. ¿Está Pedro?', 'Allô ? — Bonjour, c\'est Ana. Pedro est là ?'], ['Te llamaré mañana sin falta.', 'Je t\'appellerai demain sans faute.'], ['¿Le puede decir que he llamado?', 'Pouvez-vous lui dire que j\'ai appelé ?']],
      'Au téléphone, on se présente avec « Soy… » (Soy Marie) ou « Le llamo de parte de… » (j\'appelle de la part de…).'),
    [
      I('¿Diga? / ¿Sí?', 'Allô ?', '¿Diga? — Hola, soy Ana.', 'Allô ? — Bonjour, c\'est Ana.'),
      I('¿De parte de quién?', 'C\'est de la part de qui ?', 'Un momento, ¿de parte de quién?', 'Un instant, c\'est de la part de qui ?'),
      I('dejar un mensaje', 'laisser un message', '¿Quiere dejar un mensaje?', 'Voulez-vous laisser un message ?'),
      I('volver a llamar', 'rappeler', 'Vuelvo a llamar más tarde.', 'Je rappelle plus tard.'),
      D('Llamar al dentista', [
        ['Recepcionista', 'Clínica Dental Sonrisa, ¿dígame?', 'Clinique dentaire Sonrisa, j\'écoute ?'],
        ['Camille', 'Buenos días, soy Camille Roux. ¿Podría hablar con la doctora Ruiz?', 'Bonjour, je suis Camille Roux. Pourrais-je parler au Dr Ruiz ?'],
        ['Recepcionista', 'Lo siento, está con un paciente. ¿Quiere dejar un mensaje?', 'Désolée, elle est avec un patient. Voulez-vous laisser un message ?'],
        ['Camille', 'Sí, necesito cambiar la cita del jueves.', 'Oui, je dois changer mon rendez-vous de jeudi.'],
        ['Recepcionista', 'Muy bien. Ella la llamará esta tarde.', 'Très bien. Elle vous rappellera cet après-midi.'],
      ], [
        ['Pourquoi Camille appelle-t-elle ?', ['Changer un rendez-vous', 'Prendre un premier rendez-vous', 'Payer', 'Se plaindre']],
        ['« Ella la llamará » signifie :', ['Elle vous appellera', 'Appelez-la', 'Elle vous a appelée', 'Il faut l\'appeler']],
      ]),
      F('Mañana te ___ sin falta. (llamar)', ['llamaré', 'llamo-é', 'llamaba', 'llamé'], 'Demain je t\'appellerai sans faute.'),
      F('Este verano ___ más tiempo. (tener)', ['tendré', 'teneré', 'tendría', 'tuve'], 'Cet été j\'aurai plus de temps.'),
      C('Au téléphone, en Espagne, on décroche souvent avec :', ['¿Diga?', '¿Aló?', '¿Pronto?', '¿Bueno?'], '« ¿Aló? » et « ¿Bueno? » s\'entendent en Amérique latine.'),
      O('Pouvez-vous lui dire que j\'ai appelé ?', 'Le puede decir que he llamado', ['lo']),
      W('Je rappelle plus tard.', 'Vuelvo a llamar más tarde|Llamo más tarde|Te llamo más tarde|Le llamo más tarde|Volveré a llamar más tarde'),
      L('Un momento, ahora se pone.', 'Un instant, je vous le passe.'),
      T('Voulez-vous laisser un message ?', ['¿Quiere dejar un mensaje?', '¿Quieres dejar mensaje de voz-se?', '¿Quiere dejando un mensaje?', '¿Quiere mensaje dejar?']),
    ]),
]),

// ─────────────── B2 ───────────────
unit('es_b2_1', 'B2', 'Opiniones', 'Donner son avis, débattre', '💬', '#f43f5e', [
  lesson('Dar la opinión', 'Donner son opinion',
    G('« creo que » + indicatif / « no creo que » + subjonctif',
      `Affirmer : <b>Creo que</b> / <b>Pienso que</b> / <b>En mi opinión</b> / <b>Para mí</b> + <b>indicatif</b> : Creo que <b>es</b> caro.<br>Nier ou douter : <b>No creo que</b> / <b>Dudo que</b> + <b>subjonctif</b> : No creo que <b>sea</b> caro.<br>Accord : <b>Estoy de acuerdo</b> · <b>Tienes razón</b> · <b>Claro</b>.<br>Désaccord : <b>No estoy de acuerdo</b> · <b>Entiendo, pero…</b> · <b>No es para tanto</b> (ce n'est pas si grave).`,
      [['Creo que el turismo es bueno para la ciudad.', 'Je pense que le tourisme est bon pour la ville.'], ['No creo que sea una buena idea.', 'Je ne pense pas que ce soit une bonne idée.'], ['Entiendo lo que quieres decir, pero…', 'Je comprends ce que tu veux dire, mais…']],
      '« Estoy de acuerdo » (avec « estar ») — jamais « soy de acuerdo » ni « tengo acuerdo ».'),
    [
      I('Creo que…', 'Je pense que…', 'Creo que va a llover.', 'Je pense qu\'il va pleuvoir.'),
      I('Estoy de acuerdo', 'Je suis d\'accord', 'Estoy de acuerdo contigo.', 'Je suis d\'accord avec toi.'),
      I('Tienes razón', 'Tu as raison', '¡Tienes toda la razón!', 'Tu as entièrement raison !'),
      I('por otro lado', 'd\'un autre côté', 'Por otro lado, es muy práctico.', 'D\'un autre côté, c\'est très pratique.'),
      D('Debate: ¿coches en el centro histórico?', [
        ['Moderadora', '¿Deberíamos prohibir los coches en el centro histórico?', 'Faudrait-il interdire les voitures dans le centre historique ?'],
        ['Sara', 'Sin duda. En mi opinión, el aire estaría más limpio y las calles serían más seguras.', 'Sans aucun doute. À mon avis, l\'air serait plus propre et les rues plus sûres.'],
        ['Miguel', 'Entiendo, pero no creo que sea justo para los comerciantes. Necesitan las entregas.', 'Je comprends, mais je ne pense pas que ce soit juste pour les commerçants. Ils ont besoin des livraisons.'],
        ['Sara', 'Tiene razón. Las entregas podrían hacerse por la mañana temprano.', 'Vous avez raison. Les livraisons pourraient se faire tôt le matin.'],
        ['Miguel', 'Bueno, eso quizás funcione.', 'Bon, ça pourrait marcher.'],
      ], [
        ['Quelle est la position de Sara ?', ['Pour l\'interdiction', 'Contre', 'Sans avis', 'Pour plus de parkings']],
        ['Pourquoi « sea » après « no creo que » ?', ['Négation d\'opinion → subjonctif', 'C\'est le passé', 'C\'est une erreur', 'C\'est le futur']],
      ]),
      F('No creo que ___ una buena idea.', ['sea', 'es', 'será', 'era'], 'Je ne pense pas que ce soit une bonne idée.'),
      F('Creo que ___ razón.', ['tienes', 'tengas', 'tenga', 'tuvieras'], 'Je pense que tu as raison.', '« Creo que » affirmatif → indicatif.'),
      C('Pour contester poliment :', ['Entiendo, pero…', '¡Qué tontería!', 'Estás fatal.', 'No.']),
      O('Je ne suis pas d\'accord avec toi.', 'No estoy de acuerdo contigo', ['soy']),
      W('Tu as raison.', 'Tienes razón|Tienes toda la razón'),
      L('Por otro lado, el transporte público es más barato.', 'D\'un autre côté, les transports en commun sont moins chers.'),
      T('Je doute qu\'il vienne.', ['Dudo que venga.', 'Dudo que viene.', 'Dudo que vendrá.', 'Dudo que venir.']),
    ]),

  lesson('El subjuntivo', 'Le subjonctif présent',
    G('Le subjonctif présent (presente de subjuntivo)',
      `Formation : partir du « yo » du présent, enlever le -o, et « inverser » la voyelle :<br><b>-AR → -e</b> : hablar → (hablo) → habl<b>e</b>, habl<b>es</b>, habl<b>e</b>, habl<b>emos</b>, habl<b>éis</b>, habl<b>en</b><br><b>-ER / -IR → -a</b> : tener → (tengo) → teng<b>a</b> · hacer → (hago) → hag<b>a</b><br>Irréguliers : ser → <b>sea</b> · estar → <b>esté</b> · ir → <b>vaya</b> · saber → <b>sepa</b> · haber → <b>haya</b> · dar → <b>dé</b><br>Après : <b>espero que</b>, <b>quiero que</b>, <b>es importante que</b>, <b>ojalá</b>, <b>aunque</b> (même si), <b>para que</b>, <b>cuando</b> (futur).`,
      [['Espero que te guste el regalo.', 'J\'espère que le cadeau te plaira.'], ['Es importante que llegues a tiempo.', 'Il est important que tu arrives à l\'heure.'], ['¡Ojalá haga buen tiempo!', 'Pourvu qu\'il fasse beau !']],
      'Formules du quotidien : « ¡Que tengas un buen día! », « ¡Que te mejores! » (prompt rétablissement), « ¡Que aproveche! » (bon appétit).'),
    [
      I('Espero que…', 'J\'espère que…', 'Espero que esté bien.', 'J\'espère qu\'il va bien.'),
      I('Ojalá', 'Pourvu que…', '¡Ojalá no llueva mañana!', 'Pourvu qu\'il ne pleuve pas demain !'),
      I('aunque', 'même si / bien que', 'Aunque esté cansado, voy a salir.', 'Même si je suis fatigué, je vais sortir.'),
      I('¡Que te mejores!', 'Prompt rétablissement !', 'Estás constipado… ¡Que te mejores!', 'Tu es enrhumé… Soigne-toi bien !'),
      D('Antes de la boda (avant le mariage)', [
        ['Madre', 'Espero que esté todo listo para el sábado.', 'J\'espère que tout sera prêt pour samedi.'],
        ['Hija', 'Casi. Solo hace falta que el fotógrafo confirme la hora.', 'Presque. Il faut juste que le photographe confirme l\'heure.'],
        ['Madre', '¿Y el tiempo? ¡Ojalá no llueva!', 'Et la météo ? Pourvu qu\'il ne pleuve pas !'],
        ['Hija', 'Quizás llueva por la mañana, pero aunque esté nublado, ¡la fiesta es en el jardín!', 'Il pleuvra peut-être le matin, mais même s\'il fait gris, la fête est dans le jardin !'],
      ], [
        ['Qui doit confirmer l\'heure ?', ['Le photographe', 'Le traiteur', 'Le prêtre', 'La mère']],
        ['Où a lieu la fête ?', ['Dans le jardin', 'À l\'église', 'Au restaurant', 'À la plage']],
      ]),
      F('Espero que ___ buenas vacaciones.', ['tengas', 'tienes', 'tendrás', 'tuvieras'], 'J\'espère que tu passeras de bonnes vacances.'),
      F('Es importante que nosotros ___ temprano.', ['salgamos', 'salimos', 'saldremos', 'salíamos'], 'Il est important que nous partions tôt.'),
      C('Subjonctif présent de « ir » (yo) :', ['vaya', 'voy', 'iba', 'fuera']),
      O('J\'espère que tu vas bien.', 'Espero que estés bien', ['estás']),
      W('Pourvu qu\'il ne pleuve pas !', '¡Ojalá no llueva!|Ojalá no llueva|Espero que no llueva'),
      L('Quizás vengan a cenar con nosotros.', 'Peut-être qu\'ils viendront dîner avec nous.'),
      T('Même s\'il fait froid, je vais nager.', ['Aunque haga frío, voy a nadar.', 'Aunque hace frío de, voy nadar.', 'Aunque haga frío, voy nadar.', 'Mismo si hace frío, voy a nadar.']),
    ]),

  lesson('Si yo fuera…', 'Si j\'étais…',
    G('L\'hypothèse : imparfait du subjonctif + conditionnel',
      `Hypothèse irréelle : <b>Si</b> + <b>imperfecto de subjuntivo</b>, + <b>condicional</b>.<br>Formation : 3e personne du pluriel du passé simple – <b>-ron</b> + <b>-ra</b> : hablaron → habla<b>ra</b> · tuvieron → tuvie<b>ra</b> · fueron → fue<b>ra</b> · pudieron → pudie<b>ra</b> · hicieron → hicie<b>ra</b>.<br>Conditionnel : infinitif + <b>-ía</b> : compraría, viviría (irréguliers comme au futur : tendría, haría, diría, podría).<br>→ <b>Si tuviera</b> dinero, <b>viajaría</b> por el mundo.`,
      [['Si fuera rico, viajaría por el mundo.', 'Si j\'étais riche, je voyagerais autour du monde.'], ['¿Qué harías si perdieras el trabajo?', 'Que ferais-tu si tu perdais ton travail ?'], ['Yo que tú, aceptaría.', 'À ta place, j\'accepterais.']],
      'Jamais de conditionnel après « si » : « Si tendría » est une faute très fréquente. On dit « Si tuviera ».'),
    [
      I('Yo que tú…', 'À ta place…', 'Yo que tú, la llamaría.', 'À ta place, je l\'appellerais.'),
      I('Me gustaría…', 'J\'aimerais…', 'Me gustaría vivir en el extranjero.', 'J\'aimerais vivre à l\'étranger.'),
      I('si me tocara la lotería', 'si je gagnais au loto', 'Si me tocara la lotería, dejaría de trabajar.', 'Si je gagnais au loto, j\'arrêterais de travailler.'),
      I('si pudiera', 'si je pouvais', 'Si pudiera, me quedaría una semana más.', 'Si je pouvais, je resterais une semaine de plus.'),
      D('La vida soñada', [
        ['Tomás', '¿Qué harías si no tuvieras que trabajar?', 'Que ferais-tu si tu n\'avais pas besoin de travailler ?'],
        ['Jade', 'Daría la vuelta al mundo en velero. ¿Y tú?', 'Je ferais le tour du monde en voilier. Et toi ?'],
        ['Tomás', 'Si tuviera dinero, abriría una casa rural en Asturias.', 'Si j\'avais de l\'argent, j\'ouvrirais un gîte dans les Asturies.'],
        ['Jade', '¡Yo que tú, empezaría a ahorrar ya!', 'À ta place, je commencerais à économiser tout de suite !'],
      ], [
        ['Quel est le rêve de Tomás ?', ['Ouvrir un gîte dans les Asturies', 'Faire le tour du monde', 'Arrêter de travailler', 'Gagner au loto']],
        ['« Yo que tú » signifie :', ['À ta place', 'Moi et toi', 'Si j\'étais avec toi', 'Toi plutôt que moi']],
      ]),
      F('Si yo ___ rico, compraría un barco.', ['fuera', 'sería', 'soy', 'era'], 'Si j\'étais riche, j\'achèterais un bateau.'),
      F('Si ___ tiempo, aprendería a tocar la guitarra.', ['tuviera', 'tendría', 'tenga', 'tenía'], 'Si j\'avais le temps, j\'apprendrais la guitare.'),
      C('Quelle phrase est correcte ?', ['Si pudiera, iría contigo.', 'Si podría, iría contigo.', 'Si puedo, iría contigo.', 'Si pudiera, iré contigo.']),
      O('À ta place, je n\'accepterais pas.', 'Yo que tú no aceptaría', ['aceptara']),
      W('J\'aimerais vivre en Espagne.', 'Me gustaría vivir en España|A mí me gustaría vivir en España'),
      L('Si viviéramos cerca del mar, nadaríamos todos los días.', 'Si nous habitions près de la mer, nous nagerions tous les jours.'),
      T('Que ferais-tu si tu gagnais au loto ?', ['¿Qué harías si te tocara la lotería?', '¿Qué harías si te tocaría la lotería?', '¿Qué haces si te toca la lotería ayer?', '¿Qué hacerías si te tocara la lotería?']),
    ]),
]),

unit('es_b2_2', 'B2', 'Contar historias', 'Raconter une histoire', '📖', '#d946ef', [
  lesson('Lo que ya había pasado', 'Ce qui s\'était passé avant',
    G('Le plus-que-parfait (pluscuamperfecto)',
      `<b>había</b> (imparfait de haber) + <b>participe passé</b> = action antérieure à une autre action passée.<br>Cuando llegué, el tren <b>ya había salido</b>.<br><b>había, habías, había, habíamos, habíais, habían</b> + participe.<br>Participes irréguliers : hecho, dicho, visto, puesto, escrito, abierto, vuelto, roto, muerto.`,
      [['Nunca había visto el mar antes de aquel viaje.', 'Je n\'avais jamais vu la mer avant ce voyage.'], ['Cuando llegó la policía, el ladrón ya se había escapado.', 'Quand la police est arrivée, le voleur s\'était déjà enfui.'], ['Estaba cansada porque no había dormido.', 'Elle était fatiguée car elle n\'avait pas dormi.']],
      'Il fonctionne exactement comme le plus-que-parfait français : « j\'avais fait » = « había hecho ».'),
    [
      I('ya había…', 'avait déjà…', 'La película ya había empezado.', 'Le film avait déjà commencé.'),
      I('darse cuenta de', 'se rendre compte de', 'Me di cuenta de que había perdido la cartera.', 'Je me suis rendu compte que j\'avais perdu mon portefeuille.'),
      I('nunca había…', 'n\'avait jamais…', 'Nunca había viajado en avión.', 'Je n\'avais jamais pris l\'avion.'),
      I('olvidarse de', 'oublier', 'Me olvidé del pasaporte.', 'J\'ai oublié mon passeport.'),
      D('Un mal comienzo de vacaciones', [
        ['Nina', '¿Qué tal empezaron las vacaciones?', 'Comment ont commencé les vacances ?'],
        ['Yann', '¡Fatal! En el aeropuerto me di cuenta de que me había dejado el pasaporte en casa.', 'Une catastrophe ! À l\'aéroport, je me suis rendu compte que j\'avais laissé mon passeport à la maison.'],
        ['Nina', '¡Qué horror! ¿Y qué hiciste?', 'L\'horreur ! Et qu\'as-tu fait ?'],
        ['Yann', 'Mi vecina me lo trajo, pero cuando llegó, el avión ya había despegado.', 'Ma voisine me l\'a apporté, mais quand elle est arrivée, l\'avion avait déjà décollé.'],
      ], [
        ['Qu\'avait oublié Yann ?', ['Son passeport', 'Ses billets', 'Sa valise', 'Son téléphone']],
        ['« me lo trajo » =', ['elle me l\'a apporté', 'elle m\'a apporté', 'elle l\'a apporté', 'je l\'ai apporté']],
      ]),
      F('Cuando llegué, ellos ya ___ cenado.', ['habían', 'han', 'hubieron', 'había'], 'Quand je suis arrivé, ils avaient déjà dîné.'),
      F('Nunca había ___ esa película.', ['visto', 'vido', 'vi', 'ver'], 'Je n\'avais jamais vu ce film.'),
      C('« Elle avait déjà tout fait » :', ['Ya lo había hecho todo.', 'Ya lo había hacido todo.', 'Ya lo ha hecho todo ayer.', 'Ya hacía todo hecho.']),
      O('Le train était déjà parti.', 'El tren ya había salido', ['ha']),
      W('J\'ai oublié mon passeport.', 'Me olvidé del pasaporte|Olvidé el pasaporte|Me he olvidado del pasaporte|Olvidé mi pasaporte|Me olvidé de mi pasaporte|He olvidado el pasaporte'),
      L('Cuando llegamos, el restaurante ya había cerrado.', 'Quand nous sommes arrivés, le restaurant avait déjà fermé.'),
      T('Je me suis rendu compte que j\'avais perdu mes clés.', ['Me di cuenta de que había perdido las llaves.', 'Me di cuenta que he perdido las llaves ayer.', 'Me dio cuenta de que había perdido las llaves.', 'Me di cuenta de que perdía las llaves de.']),
    ]),

  lesson('Estilo indirecto', 'Rapporter des paroles',
    G('Le discours indirect',
      `Comme en français, on « recule » les temps :<br>« Estoy cansado » → Dijo que <b>estaba</b> cansado.<br>« Voy a llamar » → Dijo que <b>iba a</b> llamar.<br>« Compré un coche » → Dijo que <b>había comprado</b> un coche.<br>« Llamaré » → Dijo que <b>llamaría</b>.<br>Questions : Preguntó <b>si</b> quería venir. / Preguntó <b>dónde</b> vivía.<br>Ordres : « ¡Llámame! » → Me pidió <b>que</b> lo <b>llamara</b> (subjonctif imparfait).`,
      [['Me dijo que se mudaba a Madrid.', 'Elle m\'a dit qu\'elle déménageait à Madrid.'], ['Preguntó si teníamos reserva.', 'Il a demandé si nous avions une réservation.'], ['Me pidió que esperara.', 'Il m\'a demandé d\'attendre.']],
      '« pedir » = demander quelque chose (une faveur) ; « preguntar » = poser une question. « Me pidió un favor » / « Me preguntó la hora ».'),
    [
      I('decir que', 'dire que', 'Dijo que llegaba tarde.', 'Elle a dit qu\'elle arrivait en retard.'),
      I('preguntar si', 'demander si', 'Preguntó si necesitaba ayuda.', 'Il a demandé si j\'avais besoin d\'aide.'),
      I('pedir que', 'demander de', 'Me pidió que cerrara la puerta.', 'Il m\'a demandé de fermer la porte.'),
      I('prometer', 'promettre', 'Prometió que vendría.', 'Il a promis qu\'il viendrait.'),
      D('Novedades en la oficina', [
        ['Rita', '¿Hablaste ayer con Bruno?', 'Tu as parlé à Bruno hier ?'],
        ['Zoe', '¡Sí! Me dijo que se iba de la empresa.', 'Oui ! Il m\'a dit qu\'il quittait l\'entreprise.'],
        ['Rita', '¿En serio? ¿Te dijo por qué?', 'Sérieux ? Il t\'a dit pourquoi ?'],
        ['Zoe', 'Dijo que había encontrado trabajo en Canadá y que se mudaría en marzo.', 'Il a dit qu\'il avait trouvé du travail au Canada et qu\'il déménagerait en mars.'],
        ['Rita', '¡Ah! La semana pasada me preguntó si conocía a alguien en Montreal… ¡ahora lo entiendo!', 'Ah ! La semaine dernière il m\'a demandé si je connaissais quelqu\'un à Montréal… maintenant je comprends !'],
      ], [
        ['Où Bruno va-t-il travailler ?', ['Au Canada', 'Aux États-Unis', 'En France', 'Au Mexique']],
        ['Quand déménage-t-il ?', ['En mars', 'En mai', 'La semaine prochaine', 'Il ne sait pas']],
      ]),
      F('Ella dijo que ___ cansada.', ['estaba', 'está', 'estuvo', 'estará'], 'Elle a dit qu\'elle était fatiguée.'),
      F('Me ___ si quería un café.', ['preguntó', 'pidió', 'dijo', 'contó'], 'Il m\'a demandé si je voulais un café.'),
      C('« Te llamaré », dijo → Dijo que…', ['me llamaría', 'te llamaré', 'me llama', 'me llamó']),
      O('Il a demandé si nous étions français.', 'Preguntó si éramos franceses', ['somos']),
      W('Il a dit qu\'il était fatigué.', 'Dijo que estaba cansado|Él dijo que estaba cansado'),
      L('Prometió que vendría a cenar con nosotros.', 'Il a promis qu\'il viendrait dîner avec nous.'),
      T('Elle m\'a demandé de l\'attendre.', ['Me pidió que la esperara.', 'Me preguntó que la esperara.', 'Me pidió esperarla de.', 'Me dijo que la espero.']),
    ]),

  lesson('Cuando llegues…', 'Le subjonctif pour le futur',
    G('« cuando » + subjonctif : parler d\'un moment futur',
      `Le français dit « quand tu arriveras » (futur) ; l'espagnol utilise le <b>subjonctif présent</b> après <b>cuando, en cuanto</b> (dès que), <b>hasta que</b>, <b>antes de que</b>, <b>mientras</b> quand l'action est future :<br><b>Cuando llegues</b>, llámame. <b>En cuanto sepa</b> algo, te lo digo.<br>Mais pour une habitude ou un fait passé → indicatif : <b>Cuando llego</b> a casa, ceno. / <b>Cuando llegué</b>, cené.`,
      [['Cuando llegues, llámame.', 'Quand tu arriveras, appelle-moi.'], ['En cuanto pueda, te ayudo.', 'Dès que je pourrai, je t\'aide.'], ['Espera aquí hasta que vuelva.', 'Attends ici jusqu\'à ce que je revienne.']],
      'Jamais de futur après « cuando » : « Cuando llegarás » est une faute typique des francophones. On dit « Cuando llegues ».'),
    [
      I('cuando puedas', 'quand tu pourras', 'Llámame cuando puedas.', 'Appelle-moi quand tu pourras.'),
      I('en cuanto', 'dès que', 'En cuanto sepa algo, te aviso.', 'Dès que je saurai quelque chose, je te préviens.'),
      I('hasta que', 'jusqu\'à ce que', 'No me voy hasta que termines.', 'Je ne pars pas avant que tu aies fini.'),
      I('como quieras', 'comme tu veux', 'Puedes pagar como quieras.', 'Tu peux payer comme tu veux.'),
      D('Instrucciones antes del viaje', [
        ['Madre', 'Cuando llegues al aeropuerto, mándame un mensaje.', 'Quand tu arriveras à l\'aéroport, envoie-moi un message.'],
        ['Hugo', 'Vale. ¿Y si el vuelo se retrasa?', 'D\'accord. Et si le vol a du retard ?'],
        ['Madre', 'Si se retrasa, llámame. En cuanto sepas la hora de llegada, avisa a tu tía.', 'S\'il a du retard, appelle-moi. Dès que tu connaîtras l\'heure d\'arrivée, préviens ta tante.'],
        ['Hugo', 'De acuerdo. ¡Y cuando tenga tiempo, te compro un regalo!', 'D\'accord. Et quand j\'aurai le temps, je t\'achète un cadeau !'],
      ], [
        ['Que doit faire Hugo en arrivant à l\'aéroport ?', ['Envoyer un message', 'Appeler sa tante', 'Acheter un cadeau', 'Prendre un taxi']],
        ['Qui doit-il prévenir de l\'heure d\'arrivée ?', ['Sa tante', 'Sa mère', 'Son père', 'Son ami']],
      ]),
      F('Cuando ___ a Madrid, avísame.', ['llegues', 'llegas', 'llegarás', 'llegaste'], 'Quand tu arriveras à Madrid, préviens-moi.'),
      F('En cuanto ___ tiempo, iré al museo.', ['tenga', 'tengo', 'tendré', 'tuviera'], 'Dès que j\'aurai le temps, j\'irai au musée.'),
      C('Quelle phrase est correcte ?', ['Cuando seas mayor, lo entenderás.', 'Cuando serás mayor, lo entenderás.', 'Cuando eres mayor, lo entenderás mañana.', 'Cuando fueras mayor, lo entiendes.']),
      O('Appelle-moi quand tu pourras.', 'Llámame cuando puedas', ['puedes']),
      W('Dès que je saurai, je te le dis.', 'En cuanto sepa, te lo digo|En cuanto lo sepa, te lo digo|En cuanto sepa te lo digo|Cuando lo sepa, te lo digo|Cuando sepa, te lo digo'),
      L('En cuanto llegue a casa, te llamo.', 'Dès que j\'arrive à la maison, je t\'appelle.'),
      T('Attends jusqu\'à ce que je revienne.', ['Espera hasta que vuelva.', 'Espera hasta que vuelvo.', 'Espera hasta que volveré.', 'Espera hasta volver yo que.']),
    ]),
]),

unit('es_b2_3', 'B2', 'Español auténtico', 'Parler comme un Espagnol', '🚀', '#eab308', [
  lesson('Se vende, se habla', 'Le « se » impersonnel et le passif',
    G('Le « se » impersonnel et la voix passive',
      `Là où le français dit « on », l'espagnol utilise souvent <b>se</b> : <b>Se habla</b> inglés (on parle anglais). <b>Se vende</b> (à vendre). <b>Se alquila</b> (à louer). <b>No se puede</b> fumar.<br>Le verbe s'accorde avec le sujet : <b>Se venden</b> pisos. <b>Se alquilan</b> habitaciones.<br>Passif : <b>ser + participe</b> (accordé) : El puente <b>fue construido</b> en 1890. La catedral <b>fue terminada</b> en el siglo XVI.`,
      [['Aquí se habla francés.', 'Ici, on parle français.'], ['Se alquilan bicicletas.', 'Location de vélos.'], ['La Sagrada Familia fue diseñada por Gaudí.', 'La Sagrada Familia a été conçue par Gaudí.']],
      'Sur les panneaux en Espagne : « Se vende » (à vendre), « Se alquila » (à louer), « Se busca camarero » (on recherche un serveur), « Prohibido fumar ».'),
    [
      I('Se vende / Se alquila', 'À vendre / À louer', 'Se vende piso de tres dormitorios.', 'Appartement trois chambres à vendre.'),
      I('Se busca…', 'On recherche…', 'Se busca cocinero con experiencia.', 'On recherche un cuisinier expérimenté.'),
      I('fue construido', 'a été construit', 'Este palacio fue construido en 1840.', 'Ce palais a été construit en 1840.'),
      I('prohibido', 'interdit', 'Prohibido aparcar.', 'Stationnement interdit.'),
      D('Una visita guiada en Granada', [
        ['Guía', 'La Alhambra fue construida entre los siglos XIII y XIV.', 'L\'Alhambra a été construite entre le XIIIe et le XIVe siècle.'],
        ['Turista', '¿Y se puede visitar todo el palacio?', 'Et on peut visiter tout le palais ?'],
        ['Guía', 'Casi todo, pero las entradas se compran con antelación.', 'Presque tout, mais les billets s\'achètent à l\'avance.'],
        ['Turista', '¿Se pueden hacer fotos?', 'On peut prendre des photos ?'],
        ['Guía', 'Sí, pero no se puede usar flash dentro.', 'Oui, mais on ne peut pas utiliser le flash à l\'intérieur.'],
      ], [
        ['Quand l\'Alhambra a-t-elle été construite ?', ['XIIIe-XIVe siècles', 'Au XIXe siècle', 'Au XVIe siècle', 'Au XXe siècle']],
        ['Qu\'est-ce qui est interdit ?', ['Le flash', 'Les photos', 'Les enfants', 'Les sacs']],
      ]),
      F('___ habitaciones. (panneau : chambres à louer)', ['Se alquilan', 'Se alquila', 'Alquilarse', 'Alquilan se'], 'Chambres à louer.', 'Sujet pluriel (habitaciones) → verbe pluriel.'),
      F('La catedral fue ___ en el siglo XVI.', ['terminada', 'terminado', 'terminó', 'terminar'], 'La cathédrale a été terminée au XVIe siècle.', '« la catedral » est féminin.'),
      C('« Ici on parle anglais » :', ['Aquí se habla inglés.', 'Aquí uno habla se inglés.', 'Aquí se hablan inglés.', 'Aquí habla-se inglés.']),
      O('Il est interdit de fumer.', 'Está prohibido fumar', ['prohíbe']),
      W('À vendre.', 'Se vende'),
      L('Este monasterio fue construido en el siglo dieciséis.', 'Ce monastère a été construit au XVIe siècle.'),
      T('On recherche un serveur.', ['Se busca camarero.', 'Se buscan camarero.', 'Uno busca un camarero.', 'Busca-se camarero.']),
    ]),

  lesson('Expresiones', 'Expressions idiomatiques',
    G('Parler comme un Espagnol',
      `<b>¡Qué guay!</b> = Trop bien ! · <b>¡Vale!</b> = D'accord · <b>¡Qué pasada!</b> = C'est génial ! · <b>¡Venga!</b> = Allez ! / Bon !<br><b>Estar hecho polvo</b> = être crevé · <b>Costar un ojo de la cara</b> = coûter les yeux de la tête · <b>Meter la pata</b> = faire une gaffe · <b>Tomar el pelo</b> = faire marcher, se moquer · <b>Ser pan comido</b> = être du gâteau · <b>Estar en las nubes</b> = être dans la lune.`,
      [['¡Este concierto ha sido una pasada!', 'Ce concert était génial !'], ['El hotel costó un ojo de la cara.', 'L\'hôtel a coûté les yeux de la tête.'], ['Hoy estoy hecho polvo.', 'Aujourd\'hui je suis crevé.']],
      '« Tío / tía » s\'entend partout entre amis en Espagne : « ¡Tío, qué guay! » (Mec, trop bien !). Familier, à éviter avec des inconnus.'),
    [
      I('¡Qué guay!', 'Trop bien !', '¡Qué guay! Me encanta.', 'Trop bien ! J\'adore.'),
      I('estar hecho polvo', 'être crevé', 'Después del viaje estaba hecha polvo.', 'Après le voyage j\'étais crevée.'),
      I('costar un ojo de la cara', 'coûter les yeux de la tête', 'Las entradas cuestan un ojo de la cara.', 'Les places coûtent une fortune.'),
      I('meter la pata', 'faire une gaffe', 'Metí la pata en la reunión.', 'J\'ai fait une gaffe en réunion.'),
      D('En la terraza', [
        ['Rita', 'Bueno, ¿qué tal el concierto?', 'Alors, c\'était comment le concert ?'],
        ['Jorge', '¡Una pasada! Pero las entradas costaron un ojo de la cara.', 'Génial ! Mais les places ont coûté les yeux de la tête.'],
        ['Rita', 'Ya… ¿Y Pedro fue con vosotros?', 'Ouais… Et Pedro est venu avec vous ?'],
        ['Jorge', 'No, metió la pata: ¡compró las entradas para el día equivocado!', 'Non, il a fait une gaffe : il a acheté les places pour le mauvais jour !'],
        ['Rita', '¡Pobre! Estará de mal humor.', 'Le pauvre ! Il doit être de mauvaise humeur.'],
      ], [
        ['Qu\'a fait Pedro ?', ['Il a acheté des places pour le mauvais jour', 'Il a perdu ses places', 'Il était malade', 'Il a raté le train']],
        ['« ¡Pobre! » signifie :', ['Le pauvre !', 'Quel idiot !', 'Tant mieux !', 'Bien fait !']],
      ]),
      F('Esa chaqueta costó un ojo de la ___.', ['cara', 'cabeza', 'mano', 'boca'], 'Cette veste a coûté les yeux de la tête.'),
      F('Después de correr diez kilómetros, estoy hecho ___.', ['polvo', 'pan', 'pata', 'nube'], 'Après avoir couru dix kilomètres, je suis crevé.'),
      C('« Meter la pata » signifie :', ['Faire une gaffe', 'Marcher beaucoup', 'Se blesser', 'Danser']),
      O('C\'est du gâteau !', 'Es pan comido', ['está']),
      W('Trop bien ! (familier)', '¡Qué guay!|Qué guay|¡Qué pasada!|Qué pasada'),
      L('¡Venga, vale, nos vemos mañana!', 'Allez, d\'accord, on se voit demain !'),
      T('Tu te moques de moi ?', ['¿Me estás tomando el pelo?', '¿Me estás tomando la pierna?', '¿Me estás metiendo la pata?', '¿Me tomas el cabello?']),
    ]),

  lesson('Falsos amigos', 'Les faux amis',
    G('Les faux amis espagnol-français les plus traîtres',
      `<b>embarazada</b> = ENCEINTE (≠ embarrassée → <i>avergonzada</i>)<br><b>constipado</b> = enrhumé (≠ constipé → <i>estreñido</i>)<br><b>el éxito</b> = le succès (≠ la sortie → <i>la salida</i>)<br><b>largo</b> = long (≠ large → <i>ancho</i>)<br><b>la carpeta</b> = la chemise, le dossier (≠ le tapis → <i>la alfombra</i>)<br><b>bizarro</b> = courageux (≠ bizarre → <i>raro</i>)<br><b>la oficina</b> = le bureau · <b>el despacho</b> = le bureau (pièce) · <b>la tienda</b> = le magasin`,
      [['Estoy muy avergonzada.', 'Je suis très embarrassée.'], ['La película fue un éxito.', 'Le film a été un succès.'], ['¿Dónde está la salida?', 'Où est la sortie ?']],
      'Le piège qui fait toujours rire : « Estoy embarazada » = « Je suis enceinte ». Pour « je suis gênée », dites « Me da vergüenza » ou « Estoy avergonzada ».'),
    [
      I('embarazada', 'enceinte', 'Mi hermana está embarazada.', 'Ma sœur est enceinte.'),
      I('el éxito / la salida', 'le succès / la sortie', 'La salida está a la derecha.', 'La sortie est à droite.'),
      I('largo / ancho', 'long / large', 'Este pantalón es demasiado largo.', 'Ce pantalon est trop long.'),
      I('raro', 'bizarre', '¡Qué olor más raro!', 'Quelle odeur bizarre !'),
      D('En la tienda', [
        ['Dependienta', 'Hola, ¿qué tal le queda el vestido?', 'Bonjour, comment vous va la robe ?'],
        ['Rose', 'Es bonito, pero es un poco largo. Y estoy un poco avergonzada… creo que lo he manchado.', 'Elle est jolie, mais un peu longue. Et je suis un peu gênée… je crois que je l\'ai tachée.'],
        ['Dependienta', 'No se preocupe, no pasa nada. ¿Quiere probar uno más corto?', 'Ne vous inquiétez pas, ce n\'est rien. Vous voulez en essayer une plus courte ?'],
        ['Rose', 'Sí, gracias. ¿Y dónde está la salida al parking?', 'Oui, merci. Et où est la sortie vers le parking ?'],
        ['Dependienta', 'Al fondo, a la izquierda.', 'Au fond, à gauche.'],
      ], [
        ['Quel est le problème de la robe ?', ['Elle est trop longue', 'Elle est trop large', 'Elle est trop chère', 'Elle est trop courte']],
        ['« avergonzada » signifie :', ['gênée, embarrassée', 'enceinte', 'fâchée', 'fatiguée']],
      ]),
      F('Me da mucha ___. (je suis très gênée)', ['vergüenza', 'embarazada', 'éxito', 'raro'], 'Je suis très gênée.'),
      F('¿Dónde está la ___? (la sortie)', ['salida', 'éxito', 'sortida', 'puerta de éxito'], 'Où est la sortie ?'),
      C('« Mi amiga está embarazada » =', ['Mon amie est enceinte', 'Mon amie est gênée', 'Mon amie est fâchée', 'Mon amie est enrhumée']),
      O('Ce pantalon est trop long.', 'Este pantalón es demasiado largo', ['ancho']),
      W('C\'est bizarre.', 'Es raro|Qué raro|¡Qué raro!|Es extraño'),
      L('La película fue un gran éxito.', 'Le film a été un grand succès.'),
      T('Je suis enrhumé.', ['Estoy constipado.', 'Soy constipado.', 'Estoy estreñido.', 'Tengo constipado.'], '« Estreñido » = constipé.'),
    ]),
]),

]);
})();
